  title         = "4.1.3 Ensure SQL server's Transparent Data Encryption (TDE) protector is encrypted with Customer-managed key"
  description   = "Transparent Data Encryption (TDE) with Customer-managed key support provides increased transparency and control over the TDE Protector, increased security with an HSM-backed external service, and promotion of separation of duties."
  query         = query.sql_server_tde_protector_cmk_encrypted
  documentation = file("./cis_v150/docs/cis_v150_4_1_3.md")

  tags = merge(local.cis_v150_4_1_common_tags, {
    cis_item_id = "4.1.3"
    cis_level   = "2"
    cis_type    = "automated"
    service     = "Azure/SQL"
  })
}

query_definitions.source:
query "sql_server_tde_protector_cmk_encrypted" {
  sql = <<-EOQ
    select
      s.id as resource,
      case
        when encryption ->> 'kind' = 'servicemanaged' then 'alarm'
        else 'ok'
      end as status,
      case
        when encryption ->> 'kind' = 'servicemanaged' then s.name || ' TDE protector not encrypted with CMK.'
        else s.name || ' TDE protector encrypted with CMK.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "s.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "s.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_sql_server s
      cross join lateral jsonb_array_elements(encryption_protector) encryption
      left join azure_subscription sub on sub.subscription_id = s.subscription_id;
  EOQ
}

