query_definitions.source:
query "postgres_db_server_log_duration_on" {
  sql = <<-EOQ
    select
      s.id as resource,
      case
        when lower(config -> 'ConfigurationProperties' ->> 'value') != 'on' then 'alarm'
        else 'ok'
      end as status,
      case
        when lower(config -> 'ConfigurationProperties' ->> 'value') != 'on' then name || ' server parameter log_duration off.'
        else name || ' server parameter log_duration on.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "s.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "s.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_postgresql_server s
      cross join lateral jsonb_array_elements(server_configurations) config
      left join azure_subscription as sub on sub.subscription_id = s.subscription_id
    where
      config ->> 'Name' = 'log_duration';
  EOQ
}

