Code.NativeIaC:
```bicep
// Enable Azure Backup protection for an existing VM in an existing Recovery Services vault
param vmId string            // e.g., /subscriptions/<sub>/resourceGroups/<rg>/providers/Microsoft.Compute/virtualMachines/<vm>
param vaultName string
param vaultRg string
param policyId string        // e.g., /subscriptions/<sub>/resourceGroups/<rg>/providers/Microsoft.RecoveryServices/vaults/<vault>/backupPolicies/<policy>

resource vault 'Microsoft.RecoveryServices/vaults@2023-04-01' existing = {
  name: vaultName
  scope: resourceGroup(vaultRg)
}

var vmRg = split(split(vmId, '/resourceGroups/')[1], '/')[0]
var vmName = split(vmId, '/virtualMachines/')[1]

resource protect 'Microsoft.RecoveryServices/vaults/backupFabrics/protectionContainers/protectedItems@2023-02-01' = {
  // critical: this resource creates the protected item, enabling backup for the VM
  name: '${vault.name}/Azure/protectionContainers/iaasvmcontainer;iaasvmcontainerv2;${vmRg};${vmName}/protectedItems/VM;iaasvmcontainerv2;${vmRg};${vmName}'
  properties: {
    protectedItemType: 'Microsoft.Compute/virtualMachines' // critical: VM backup item type
    sourceResourceId: vmId                                 // critical: target VM to protect
    policyId: policyId                                     // critical: associates the VM with a backup policy
  }
}
```

```bicep
// Create/ensure a VM backup policy with daily retention >= minimum
resource rv 'Microsoft.RecoveryServices/vaults@2023-01-01' existing = {
  name: '<example_resource_name>'
}

resource vmPolicy 'Microsoft.RecoveryServices/vaults/backupPolicies@2023-02-01' = {
  name: '${rv.name}/<example_resource_name>'
  properties: {
    backupManagementType: 'AzureIaasVM'
    schedulePolicy: {
      schedulePolicyType: 'SimpleSchedulePolicyV2'
      scheduleRunFrequency: 'Daily'
      scheduleRunTimes: ['2020-01-01T23:00:00Z']
    }
    retentionPolicy: {
      retentionPolicyType: 'LongTermRetentionPolicy'
      dailySchedule: {
        retentionTimes: ['2020-01-01T23:00:00Z']
        retentionDuration: {
          count: 7 // CRITICAL: sets daily retention to at least the minimum required days
          durationType: 'Days' // explains the unit
        }
      }
    }
  }
}
```

