query "keyvault_secret_expiration_set" {
  sql = <<-EOQ
    select
      kvs.id as resource,
      case
        when enabled and expires_at is null then 'alarm'
        else 'ok'
      end as status,
      vault_name || ' secret ' || name ||
      case
