def _join(rows, parent, suffix):
    expected = parent.casefold().rstrip("/") + suffix.casefold()
    found = [row for row in rows if get(row, "id", str).casefold() == expected]
    if len(found) != 1:
        raise Unavailable("required child absent or ambiguous: " + suffix)
    return found[0]

