def _parent(item, index, component):
    identity = get(item, 'id', str)
    match = re.fullmatch(r'(/subscriptions/[^/]+/resourceGroups/[^/]+/providers/Microsoft.KeyVault/vaults/[^/]+)/' + component + r'/[^/]+', identity, re.I)
